import { z } from "zod";

/** The body a client sends to create an order. */
export const createOrderBody = z.object({ name: z.string() });

/**
 * A SCIM user as a directory sends it.
 *
 * foreign-spec: RFC 7643 says a server ignores attributes it does not advertise.
 */
export const scimUserBody = z.object({ userName: z.string() });

/** The body a client sends to rename an order. */
export const renameOrderBody = z.strictObject({ name: z.string() });
